args<-commandArgs(TRUE);O<-args[1];suppressPackageStartupMessages(library(decontX));suppressPackageStartupMessages(library(Matrix));T<-file.path(O,"inputs/decontx_diagnostic");gene<-read.delim(file.path(T,"genes.tsv"));samples<-c("Saline_1","Saline_2","Saline_3","Silica_1","Silica_2","Silica_3");query<-c("DUSP5","CDH1","OCLN","BMP1","H2-Q1","KLRG1","ITGAE","ITGB7","PYCARD","CASP1","GSDMD","IL1B","IL18");out<-list();metaout<-list();for(s in samples){cat("START",s,"\n");m<-read.delim(file.path(T,paste0(s,"_cells.tsv")));x<-as(readMM(file.path(T,paste0(s,".mtx"))),"dgCMatrix");rownames(x)<-gene$gene_id;colnames(x)<-m$cell;keep<-rowSums(x)>0;x<-x[keep,,drop=FALSE];res<-decontX::decontX(x,z=as.integer(factor(m$decontx_cluster)),seed=42,maxIter=500,verbose=FALSE);saveRDS(res,file.path(T,paste0(s,"_decontx.rds")));clean<-res$decontXcounts;stopifnot(identical(dim(clean),dim(x)),all(is.finite(clean@x)),all(clean@x>=0));ids<-gene$gene_id[gene$canonical%in%query];ids<-intersect(ids,rownames(x));idx<-match(ids,gene$gene_id);raw<-as.matrix(x[ids,,drop=FALSE]);dc<-as.matrix(clean[ids,,drop=FALSE]);z<-data.frame(cell=rep(colnames(x),each=length(ids)),sample=s,gene=rep(gene$canonical[idx],times=ncol(x)),raw_count=as.vector(raw),corrected_count=as.vector(dc),raw_library=rep(colSums(x),each=length(ids)),corrected_library=rep(colSums(clean),each=length(ids)));out[[s]]<-z;m$contamination<-res$contamination;metaout[[s]]<-m;cat("DONE",s,"median",median(res$contamination),"\n");flush.console()};write.table(do.call(rbind,out),gzfile(file.path(O,"06_novelty/decontx_selected_gene_cell_counts.tsv.gz")),sep="\t",row.names=FALSE,quote=FALSE);write.table(do.call(rbind,metaout),gzfile(file.path(O,"06_novelty/decontx_cell_metadata.tsv.gz")),sep="\t",row.names=FALSE,quote=FALSE);writeLines(capture.output(sessionInfo()),file.path(O,"provenance/decontx_session.txt"))